/* Interactive device-management preview with local sample data. */
const paths={device:'<rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8m-4-4v4"/>',terminal:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m7 9 3 3-3 3m6 0h4"/>',shield:'<path d="m12 3 8 3v5c0 5-4 8-8 10-4-2-8-5-8-10V6l8-3Z"/><path d="m8.5 12 2.5 2.5 4.5-5"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',runner:'<path d="m9 6 9 6-9 6V6Z"/><circle cx="12" cy="12" r="10"/>',sliders:'<path d="M3 6h10m4 0h4M3 12h4m4 0h10M3 18h10m4 0h4"/><circle cx="15" cy="6" r="2"/><circle cx="9" cy="12" r="2"/><circle cx="15" cy="18" r="2"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',network:'<rect x="8" y="3" width="8" height="6" rx="1"/><rect x="2" y="16" width="7" height="5" rx="1"/><rect x="15" y="16" width="7" height="5" rx="1"/><path d="M12 9v4M5.5 16v-3h13v3"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.01"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 5 7 7-7 7"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',topology:'<circle cx="12" cy="12" r="2"/><circle cx="5" cy="5" r="2"/><circle cx="19" cy="5" r="2"/><circle cx="5" cy="19" r="2"/><circle cx="19" cy="19" r="2"/><path d="m6.5 6.5 4 4m3 0 4-4m-11 11 4-4m3 0 4 4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5 8a7 7 0 0 1 12-3l3 4M4 15l3 4a7 7 0 0 0 12-3"/>',radar:'<path d="M21 12a9 9 0 1 1-9-9m5 9a5 5 0 1 1-5-5m0 5 9-9"/><circle cx="12" cy="12" r="1"/>',link:'<path d="m10 13 4-4m-5 7-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 10a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-2 2"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8m-8 4h5"/>',server:'<rect x="4" y="3" width="16" height="7" rx="2"/><rect x="4" y="14" width="16" height="7" rx="2"/><path d="M8 6.5h.01M8 17.5h.01M12 7h4m-4 10h4"/>',laptop:'<rect x="5" y="3" width="14" height="12" rx="2"/><path d="m5 15-3 5h20l-3-5M10 17h4"/>'};
paths.eye='<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>';
paths.eyeOff='<path d="m3 3 18 18M10.6 5.1 12 5c6.5 0 10 7 10 7a18 18 0 0 1-3 3.8M6.3 6.3A19 19 0 0 0 2 12s3.5 7 10 7a11 11 0 0 0 5.7-1.7M9.9 9.9a3 3 0 0 0 4.2 4.2"/>';
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.device}</svg>`;
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon)});}
document.querySelectorAll('[data-nav]').forEach(el=>el.insertAdjacentHTML('afterbegin',icon(el.dataset.nav)));hydrate();
const $=id=>document.getElementById(id);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sampleDevices=[
 {id:'studio',name:'studio-mac',os:'macOS',icon:'device',online:true,path:'局域网',route:'直连',address:'192.0.2.24',tag:'tag:device',standby:'Tailnet',last:'刚刚'},
 {id:'build',name:'build-linux',os:'Linux',icon:'server',online:true,path:'Tailnet',route:'直连',address:'198.51.100.12',tag:'tag:device',standby:'—',last:'刚刚'},
 {id:'office',name:'office-windows',os:'Windows',icon:'device',online:true,path:'Tailnet',route:'中继',address:'203.0.113.18',tag:'tag:device',standby:'—',last:'刚刚'},
 {id:'travel',name:'travel-laptop',os:'macOS',icon:'laptop',online:false,path:'—',route:'等待上线',address:'192.0.2.38',tag:'tag:peer',standby:'—',last:'2 小时前'}
];
let scene='current',filter='all',devices=[],passwordSet=true,toastTimer,pairedSample=false;
const drawer=$('drawer');
function notify(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3200)}
function setScene(next){scene=next;devices=next==='sample'?sampleDevices.map(d=>({...d})):[];pairedSample=false;filter='all';$('search').value='';document.querySelectorAll('[data-scene]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scene===next)));document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.filter==='all');b.setAttribute('aria-pressed',String(b.dataset.filter==='all'))});render();}
function render(){
 const online=devices.filter(d=>d.online).length;
 for(const [id,n] of Object.entries({'device-count':devices.length,'all-count':devices.length,'online-count':online,'offline-count':devices.length-online,'direct-count':devices.filter(d=>d.online&&d.route==='直连').length,'relay-count':devices.filter(d=>d.online&&d.route==='中继').length}))$(id).textContent=n;
 $('data-label').textContent=scene==='sample'?'示例数据':'单设备示例';
 const query=$('search').value.trim().toLowerCase();
 const shown=devices.filter(d=>(filter==='all'||(filter==='online'?d.online:!d.online))&&`${d.name} ${d.os} ${d.address}`.toLowerCase().includes(query));
 if(devices.length===0&&!query&&filter==='all'){
  $('device-list').innerHTML=`<div class="empty-state"><div class="empty-graphic" aria-hidden="true"><span class="empty-node">${icon('laptop')}</span><span class="node-line"></span><span class="empty-node center">${icon('device')}</span><span class="node-line"></span><span class="empty-node">${icon('server')}</span></div><h3>连接你的第一台设备</h3><p>配对后，在这里查看设备状态，<br>开启远程终端、桌面控制与文件传输。</p><button class="button primary" data-action="add">${icon('plus')}添加设备</button></div>`;
 }else if(!shown.length){$('device-list').innerHTML='<div class="no-results">没有符合条件的设备</div>'}
 else{$('device-list').innerHTML=`<div class="sample-label">多设备布局演示 · 以下设备及地址均为示例</div><div class="list-head"><span>设备名称</span><span class="path-header">连接方式</span><span>状态</span><span></span></div>`+shown.map(d=>`<div class="device-row" tabindex="0" role="button" data-device="${d.id}" aria-label="查看 ${escapeHTML(d.name)} 详情"><div class="device-name"><div class="device-avatar">${icon(d.icon)}</div><div><strong>${escapeHTML(d.name)}</strong><small>${d.os} · ${d.tag}</small></div></div><div class="path-cell"><span>${d.path}</span><small>${d.route}${d.standby!=='—'?' · Tailnet 备用':''}</small></div><div><span class="status-pill ${d.online?'':'offline'}"><i class="dot"></i>${d.online?'在线':'离线'}</span><small class="last-seen">${d.last}</small></div><span class="chevron">${icon('chevron')}</span></div>`).join('')}
 const found=scene==='sample'&&!pairedSample;
 $('discovery-count').textContent=found?'1':'0';
 $('discovery-content').innerHTML=found?`<div class="discovered-item"><strong>meeting-mac <span class="badge subtle">示例</span></strong><p>macOS · 局域网</p><button class="button small full" data-action="pair-sample">配对设备 ${icon('arrow')}</button></div>`:'<div class="discovery-empty"><h3>暂未发现新设备</h3><p>让另一台设备打开 xmesh，<br>可连接的设备会出现在这里。</p></div>';
}
function openPanel(title,content,kicker='设备连接'){$('drawer-title').textContent=title;$('drawer-kicker').textContent=kicker;$('drawer-content').innerHTML=content;hydrate(drawer);if(!drawer.open)drawer.showModal();}
function addPanel(){openPanel('添加设备',`<p class="drawer-description">选择适合你的连接方式，将另一台设备加入当前设备网络。</p><button class="method drawer-option" data-action="discover">${icon('radar')}<span><strong>发现附近设备</strong><small>查看局域网与 Tailnet 中的设备</small></span>${icon('chevron')}</button><button class="method drawer-option" data-action="manual">${icon('link')}<span><strong>输入设备地址</strong><small>输入地址和对方的连接密码</small></span>${icon('chevron')}</button><button class="method drawer-option" data-action="document">${icon('file')}<span><strong>使用配对文档</strong><small>导入文档，并核对设备指纹</small></span>${icon('chevron')}</button><div class="drawer-section"><h3>让其他设备连接到本机</h3><p class="drawer-description">在另一台设备上找到 xiaosong-mac，输入本机的连接密码即可配对。</p><button class="button" data-action="password">${icon('lock')}管理本机连接密码</button></div>`)}
function passwordPanel(){openPanel('本机连接密码',`<p class="drawer-description">其他设备使用这个密码与 xiaosong-mac 配对。密码仅保存在本机，保存后无法查看。</p><div class="drawer-tip">${passwordSet?'已设置连接密码<br><span class="muted">最近修改于 2026-10-20 19:05</span>':'尚未设置连接密码'}</div><form id="password-form"><div class="field"><label for="new-password">${passwordSet?'新连接密码':'连接密码'}</label><div class="password-input"><input id="new-password" type="password" autocomplete="new-password" placeholder="输入 10–128 个字符" minlength="10" maxlength="128" aria-describedby="password-hint password-error" required><button type="button" class="password-toggle" data-password-toggle="new-password" aria-controls="new-password" aria-pressed="false" aria-label="显示密码" title="显示密码">${icon('eye')}</button></div><small id="password-hint">首尾不能包含空白。</small></div><p class="form-error" id="password-error" aria-live="polite"></p><div class="form-actions"><button class="button quiet" type="button" data-action="close">取消</button><button class="button primary" id="save-password" type="submit" disabled>保存密码</button></div></form>${passwordSet?'<div class="drawer-section"><h3>密码管理</h3><p class="drawer-description">清除后，其他设备将无法通过连接密码发起新的配对。</p><button class="button danger" data-action="clear-password">清除连接密码</button></div>':''}`,'本机设置');
 const validate=()=>{const pw=$('new-password').value;const valid=pw.length>=10&&pw.length<=128&&pw.trim()===pw;$('save-password').disabled=!valid;$('password-error').textContent=pw&&!valid?'请输入 10–128 个字符，首尾不能包含空白。':'';$('new-password').setAttribute('aria-invalid',String(Boolean(pw&&!valid)))};
 $('password-form').addEventListener('input',validate);$('password-form').addEventListener('submit',e=>{e.preventDefault();validate();if($('save-password').disabled)return;passwordSet=true;$('password-state').textContent='已设置';drawer.close();$('drawer-content').replaceChildren();notify('演示：连接密码已更新')});}
function manualPanel(discovered=false){openPanel(discovered?'配对 meeting-mac':'通过地址连接',`<button class="back-button" data-action="add">← 返回连接方式</button><p class="drawer-description">${discovered?'输入对方设备的连接密码，并核对设备指纹。':'输入对方设备的地址，以及在对方 xmesh 中设置的连接密码。'}</p>${discovered?'<div class="drawer-tip">示例设备 · meeting-mac<br>设备指纹：<span class="mono">12:34:56:78:ab:cd:ef:90</span><br><span class="muted">此指纹用于界面演示。</span></div>':''}<form id="connect-form"><label class="field"><span>连接路径</span><select id="connect-path" ${discovered?'disabled':''}><option>局域网</option><option>Tailnet</option></select></label><label class="field"><span>设备地址</span><input id="connect-address" placeholder="设备 IP 或主机名" ${discovered?'value="192.0.2.55" readonly':''} maxlength="260" required><small>${discovered?'文档保留地址，仅用于示例。':'使用所选网络路径上可访问的地址。'}</small></label><label class="field"><span>对方的连接密码</span><input id="connect-password" type="password" placeholder="请输入对方设备的连接密码" maxlength="128" autocomplete="off" required><small>10–128 个字符，首尾不能包含空白。</small></label><div class="form-actions"><button class="button quiet" type="button" data-action="close">取消</button><button id="connect-submit" class="button primary" type="submit" disabled>连接设备</button></div></form>`);
 const validate=()=>{const pw=$('connect-password').value;$('connect-submit').disabled=!$('connect-address').value.trim()||pw.length<10||pw.length>128||pw.trim()!==pw};$('connect-form').addEventListener('input',validate);$('connect-form').addEventListener('submit',e=>{e.preventDefault();validate();if($('connect-submit').disabled)return;if(discovered&&scene==='sample'&&!pairedSample){devices.push({id:'meeting',name:'meeting-mac',os:'macOS',icon:'laptop',online:true,path:'局域网',route:'直连',address:'192.0.2.55',tag:'tag:device',standby:'—',last:'刚刚'});pairedSample=true;render()}drawer.close();$('drawer-content').replaceChildren();notify(discovered?'演示：meeting-mac 已加入设备列表':'演示：配对信息已提交')});}
function documentPanel(){openPanel('使用配对文档',`<button class="back-button" data-action="add">← 返回连接方式</button><p class="drawer-description">在两台设备间交换配对文档，并通过可信渠道核对设备指纹。</p><button class="button full" data-action="export">${icon('file')}导出本机配对文档</button><div class="drawer-section"><h3>导入对方设备</h3><label class="field"><span>配对文档</span><textarea id="pair-document" placeholder="粘贴对方设备导出的 JSON 文档"></textarea></label><label class="field"><span>设备指纹</span><input id="pair-fingerprint" placeholder="输入经可信渠道核对的指纹"><small>正式配对时，指纹需与对方文档一致。</small></label><span class="muted" style="font-size:12px">授权标签</span><label class="check-label"><input type="checkbox" checked>tag:peer</label><label class="check-label"><input type="checkbox" checked>tag:device</label><button class="button primary full" data-action="import">检查并导入</button></div>`)}
function detailPanel(id){const d=devices.find(d=>d.id===id);if(!d)return;openPanel(d.name,`<div class="detail-hero"><div class="device-avatar large">${icon(d.icon)}</div><div><strong>${d.name}</strong><span class="status-pill ${d.online?'':'offline'}"><i class="dot"></i>${d.online?'在线':'离线'}</span></div></div><dl class="detail-list"><div><dt>操作系统</dt><dd>${d.os}</dd></div><div><dt>当前路径</dt><dd>${d.path}</dd></div><div><dt>连接方式</dt><dd>${d.route}</dd></div><div><dt>备用路径</dt><dd>${d.standby}</dd></div><div><dt>设备地址</dt><dd class="mono">${d.address}</dd></div><div><dt>授权标签</dt><dd>${d.tag}</dd></div><div><dt>最近在线</dt><dd>${d.last}</dd></div></dl><div class="detail-actions">${['terminal','device','folder'].map((ico,i)=>`<button class="button" data-shortcut="${['远程终端','桌面控制','文件传输'][i]}" ${!d.online?'disabled':''}>${icon(ico)}${['终端','桌面','文件'][i]}</button>`).join('')}</div><div class="drawer-section"><h3>配对管理</h3><p class="drawer-description">撤销后，这台设备需要重新配对才能访问本机。</p><button class="button danger" data-revoke="${d.id}">撤销配对</button></div>`,'设备详情 · 示例数据')}
document.addEventListener('click',e=>{
 const passwordToggle=e.target.closest('[data-password-toggle]');if(passwordToggle){const input=$(passwordToggle.dataset.passwordToggle);const visible=input.type==='password';input.type=visible?'text':'password';const label=visible?'隐藏密码':'显示密码';passwordToggle.setAttribute('aria-pressed',String(visible));passwordToggle.setAttribute('aria-label',label);passwordToggle.title=label;passwordToggle.innerHTML=icon(visible?'eyeOff':'eye');return}
 const sceneButton=e.target.closest('[data-scene]');if(sceneButton){setScene(sceneButton.dataset.scene);return}
 const theme=e.target.closest('button[data-theme]');if(theme){document.documentElement.dataset.theme=theme.dataset.theme;document.querySelectorAll('button[data-theme]').forEach(b=>{b.classList.toggle('selected',b===theme);b.setAttribute('aria-pressed',String(b===theme))});return}
 const tab=e.target.closest('[data-filter]');if(tab){filter=tab.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b===tab);b.setAttribute('aria-pressed',String(b===tab))});render();return}
 const device=e.target.closest('[data-device]');if(device){detailPanel(device.dataset.device);return}
 const shortcut=e.target.closest('[data-shortcut]');if(shortcut){notify(`演示：打开${shortcut.dataset.shortcut}`);return}
 const revoke=e.target.closest('[data-revoke]');if(revoke){const d=devices.find(d=>d.id===revoke.dataset.revoke);openPanel('撤销设备配对',`<p class="drawer-description">确定撤销与 ${d.name} 的配对？之后需要重新配对才能访问本机。</p><div class="form-actions"><button class="button" data-detail="${d.id}">取消</button><button class="button danger" data-confirm-revoke="${d.id}">确认撤销</button></div>`,'配对管理');return}
 const detail=e.target.closest('[data-detail]');if(detail){detailPanel(detail.dataset.detail);return}
 const confirmRevoke=e.target.closest('[data-confirm-revoke]');if(confirmRevoke){devices=devices.filter(d=>d.id!==confirmRevoke.dataset.confirmRevoke);render();drawer.close();notify('演示：设备配对已撤销');return}
 const action=e.target.closest('[data-action]')?.dataset.action;
 if(action==='add')addPanel();if(action==='close')drawer.close();if(action==='password')passwordPanel();if(action==='manual')manualPanel();if(action==='pair-sample')manualPanel(true);if(action==='document')documentPanel();
 if(action==='clear-password')openPanel('清除连接密码',`<p class="drawer-description">清除后，其他设备将无法通过连接密码发起新的配对。已配对设备保留现有连接。</p><div class="form-actions"><button class="button" data-action="password">取消</button><button class="button danger" data-action="confirm-clear">确认清除</button></div>`,'本机设置');
 if(action==='confirm-clear'){passwordSet=false;$('password-state').textContent='未设置';drawer.close();notify('演示：连接密码已清除')}
 if(action==='refresh'){$('refresh-copy').textContent='正在刷新…';setTimeout(()=>{$('refresh-copy').textContent='已刷新 · 每 15 秒自动发现';notify(scene==='sample'&&!pairedSample?'演示：发现 1 台可配对设备':'演示：暂未发现新的可配对设备')},550)}
 if(action==='discover')openPanel('发现设备',scene==='sample'&&!pairedSample?`<p class="drawer-description">发现 1 台可配对设备。</p><div class="drawer-tip">示例设备 · meeting-mac<br>macOS · 局域网</div><button class="button primary full" data-action="pair-sample">配对 meeting-mac</button>`:`<p class="drawer-description">暂未发现新设备。请在另一台设备上打开 xmesh，并确认双方处于可互通的网络。</p><button class="button full" data-action="refresh">${icon('refresh')}重新发现</button><div class="drawer-section"><button class="button primary full" data-action="manual">通过地址连接</button></div>`);
 if(action==='setup')openPanel('继续已有设置','<p class="drawer-description">此入口在正式应用中打开已有的设置向导，继续完成设备网络配置。</p><button class="button full" data-action="close">返回设备管理</button>','设置入口');
 if(action==='export')notify('演示：正式应用将在此生成本机配对文档');
 if(action==='import'){if(!$('pair-document').value.trim()||!$('pair-fingerprint').value.trim()){notify('请填写配对文档并核对设备指纹');return}notify('演示：正式应用将在核对文档、指纹和授权后请求确认')}
});
$('search').addEventListener('input',render);
document.addEventListener('keydown',e=>{const row=e.target.closest('[data-device]');if(row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();detailPanel(row.dataset.device)}});
drawer.addEventListener('click',e=>{if(e.target===drawer){const r=drawer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)drawer.close()}});
drawer.addEventListener('close',()=>{$('drawer-content').replaceChildren()});
render();
